using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ShiningApparatusOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/ShiningApparatus Omen Data")]
public class ShiningApparatusOmenData : OmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.ShiningApparatusOmenAction = delegate(GameObject sentinel)
		{
			omenInstance.ActivateOmenFeedback();
			OmenLogic.ActivateOmen(BattleAction, Mathf.CeilToInt(sentinel.GetComponent<CorruptionStats>().MaxCorruption / 2f), sentinel, null);
		};
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<HeveliusOmensHandler>.Instance.ShiningApparatusOmenAction = null;
	}

	public override string OmenConvertedDescription()
	{
		DefaultEffectAction defaultEffectAction = BattleAction as DefaultEffectAction;
		string omenRawLocalizedDescription = GetOmenRawLocalizedDescription();
		omenRawLocalizedDescription = Smart.Format(omenRawLocalizedDescription, defaultEffectAction.Effect.GetEffectName(), base.localizationManager.GetLocalizedRoundedUp());
		return CheckAppendCounterKeptBetweenBattlesDescription(omenRawLocalizedDescription);
	}
}
